const s = $input.first().json;
function utf8Bytes(text) {
  let total=0;
  for (const char of text) { const cp=char.codePointAt(0); total += cp<=127 ? 1 : cp<=2047 ? 2 : cp<=65535 ? 3 : 4; }
  return total;
}
for (const key of ['beforeXml','afterXml']) {
  if (typeof s[key] !== 'string' || !s[key].trim() || utf8Bytes(s[key])>2000000) throw new Error('Supply two complete XML urlset snapshots, maximum 2,000,000 UTF-8 bytes each.');
  if (/<!\s*(?:DOCTYPE|ENTITY)\b/i.test(s[key])) throw new Error('DTD and custom entities are forbidden.');
}
if (typeof s.existingRunId !== 'undefined' && typeof s.existingRunId !== 'string') throw new Error('Existing run ID must be a string.');
const existingRunId=(s.existingRunId || '').trim();
if (existingRunId && !/^[A-Za-z0-9]{17}$/.test(existingRunId)) throw new Error('Existing run ID must have 17 letters or digits.');
if (!existingRunId && s.acknowledgePaidRun !== true) throw new Error('Review the USD0.005 run cap, select your Apify credential, then set acknowledgePaidRun to true.');
return [{json:{beforeXml:s.beforeXml,afterXml:s.afterXml,existingRunId}}];

const r=$input.first().json.data;
if (!r || !/^[A-Za-z0-9]{17}$/.test(r.id || '')) throw new Error('Invalid run response; inspect Apify Console before starting again.');
if (r.actId !== '0drkAMRz8hgOphLAV') throw new Error('Saved run is not from the sitemap snapshot comparator.');
if (r.status === 'SUCCEEDED') return [{json:{runId:r.id,complete:true,run:r}}];
if (!['READY','RUNNING'].includes(r.status) || $runIndex >= 5) throw new Error('Run '+r.id+' is '+r.status+'. Inspect that run in Apify Console; do not start another paid run to recover it.');
return [{json:{runId:r.id,complete:false}}];

const original=$input.first().json;
const chosen=$('Validate settings').first().json;
if (original.beforeXml !== chosen.beforeXml || original.afterXml !== chosen.afterXml) throw new Error('Saved run input differs. Restore both original XML snapshots before resuming.');
return [{json:{runId:$('Check run status').last().json.runId}}];

const fields = ['lastmod','changefreq','priority'];
const counts = ['beforeUrls','afterUrls','added','removed','changed','unchanged'];
const fail = () => { throw new Error('Incomplete or inconsistent comparison report; inspect the saved run'); };
const integer = n => Number.isSafeInteger(n) && n >= 0 && n <= 10000;
const matching = 'exact loc text after XML decoding and outer whitespace trimming';

function metadata(value) {
  return value && !Array.isArray(value) && typeof value === 'object' &&
    Object.keys(value).length === fields.length && fields.every(f => typeof value[f] === 'string');
}

function completeResult(input, summary, rows) {
  if (!summary || summary.status !== 'complete' || summary.reportStored !== true ||
      !Array.isArray(rows) || rows.length !== 1) fail();
  const report = rows[0];
  if (!report || report.comparisonComplete !== true || report.matching !== matching ||
      !counts.every(k => integer(report[k]) && summary[k] === report[k]) ||
      !integer(report.beforeDuplicateEntries) || !integer(report.afterDuplicateEntries) ||
      report.beforeUrls + report.beforeDuplicateEntries > 5000 ||
      report.afterUrls + report.afterDuplicateEntries > 5000 ||
      report.beforeUrls !== report.removed + report.changed + report.unchanged ||
      report.afterUrls !== report.added + report.changed + report.unchanged ||
      !Array.isArray(report.changes) ||
      report.changes.length !== report.added + report.removed + report.changed) fail();
  const seen = new Set(), totals = {added:0,removed:0,changed:0};
  const changes = report.changes.map(row => {
    if (!row || typeof row.url !== 'string' || [...row.url].length >= 2048 ||
        /[\u0000-\u0020]/.test(row.url) || !/^https?:\/\//i.test(row.url) || seen.has(row.url) ||
        !Object.hasOwn(totals,row.change) || !Array.isArray(row.changedFields)) fail();
    const authority=row.url.match(/^https?:\/\/([^/?#]+)/i)?.[1];
    if (!authority || authority.includes('@') || !/^(?:\[[0-9a-f:.]+\]|[^:@]+)(?::[0-9]+)?$/i.test(authority)) fail();
    const old = row.before, next = row.after;
    if (row.change === 'added' && !(old === null && metadata(next)) ||
        row.change === 'removed' && !(metadata(old) && next === null) ||
        row.change === 'changed' && !(metadata(old) && metadata(next))) fail();
    const expected = row.change === 'changed' ? fields.filter(f => old[f] !== next[f]) : [];
    if (row.change === 'changed' && !expected.length ||
        JSON.stringify(row.changedFields) !== JSON.stringify(expected)) fail();
    seen.add(row.url); totals[row.change]++;
    return {url:row.url,change:row.change,changedFields:expected,before:old,after:next};
  });
  if (Object.entries(totals).some(([k,v]) => report[k] !== v)) fail();
  return {...Object.fromEntries([...counts,'beforeDuplicateEntries','afterDuplicateEntries'].map(k => [k,report[k]])),
    comparisonComplete:true,matching,changes,
    scope:'Supplied snapshots only. No URLs fetched, no page deletion, SEO or indexing verdict. Compare the same sitemap scope.'};
}


const checked=completeResult({}, $('Read completion summary').first().json, $input.first().json.body);
return [{json:{runId:$('Check run status').last().json.runId, ...checked}}];
